package ru.yandex.practicum.order.service; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import ru.yandex.practicum.order.dto.*; import ru.yandex.practicum.order.entity.*; import ru.yandex.practicum.order.exception.NotFoundException; import ru.yandex.practicum.order.repository.OrderRepository; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.List; @Service @RequiredArgsConstructor @Transactional(readOnly=true) public class OrderService { private final OrderRepository repository; @Transactional public OrderDto create(CreateOrderRequest r){OrderEntity o=new OrderEntity(); o.setCustomerName(r.customerName()); o.setCustomerEmail(r.customerEmail()); o.setStatus(OrderStatus.CREATED); o.setCreatedAt(LocalDateTime.now()); BigDecimal total=BigDecimal.ZERO; for(OrderItemRequest x:r.items()){OrderItem i=new OrderItem(); i.setProductId(x.productId()); i.setProductName(x.productName()); i.setQuantity(x.quantity()); i.setPrice(x.price()); o.addItem(i); total=total.add(x.price().multiply(BigDecimal.valueOf(x.quantity())));} o.setTotalPrice(total); return toDto(repository.save(o));} public OrderDto findById(Long id){return toDto(repository.findById(id).orElseThrow(()->new NotFoundException("Заказ с id="+id+" не найден")));} public List<OrderDto> findAll(){return repository.findAllByOrderByCreatedAtDesc().stream().map(this::toDto).toList();} public List<OrderDto> findByEmail(String email){return repository.findAllByCustomerEmailIgnoreCaseOrderByCreatedAtDesc(email).stream().map(this::toDto).toList();} private OrderDto toDto(OrderEntity o){List<OrderItemDto> items=o.getItems().stream().map(i->new OrderItemDto(i.getId(),i.getProductId(),i.getProductName(),i.getQuantity(),i.getPrice())).toList(); return new OrderDto(o.getId(),o.getCustomerName(),o.getCustomerEmail(),o.getStatus().name(),o.getTotalPrice(),o.getStatusDetails(),o.getCreatedAt(),items);} }
